-- Pass 121 -- Chile cluster (2026-10-28). Replay of statements actually executed
-- against project zkdguzbdopfedkffsatk. Retires 467 (invented 'International
-- Excellence Scholarship' name) and 879 (exchange-mobility tuition benefit for
-- CINDA / Latin American & Chilean Catholic university networks), on the basis of a
-- first-hand fetch of UC's official prospective-students FAQ + admissions portal.

-- 1) New official source (collision-checked against sources.url first)
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3132, 'https://www.uc.cl/informacion-para/futuros-estudiantes/', $$Información para Futuros estudiantes - FAQ incl. '¿Hay becas para extranjeros en la UC?' | Pontificia Universidad Católica de Chile (official)$$, 'uc.cl', 'scholarship', now(), true, true, now()) RETURNING id, url;

-- 2) Retire 467 (invented importer name)
UPDATE scholarships SET title = $$Pontificia Universidad Católica de Chile - 'International Excellence Scholarship' is an invented importer name; no such UC award for foreign degree students exists (retired)$$, provider = $$Pontificia Universidad Católica de Chile (UC Chile)$$, country = $$Chile$$, coverage_type = $$Unspecified$$, amount_usd_value = 0, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL, deadline = $$Retired - the named award does not exist, so there is no application round. UC's own FAQ answers the question of scholarships for foreigners with exchange-student tuition scholarships only (see description); for the university's real funding landscape see the retired audit row 695 and, for Universidad de Chile, active record 710.$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$none$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Bachelor's", "Master's", "PhD"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["RETIRED - invented importer name; UC publishes no 'International Excellence Scholarship' for foreign degree students (see description)"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$RETIRED in Pass 121 (2026-10-28) as an invented importer name. The Pontificia Universidad Católica de Chile does not publish any "International Excellence Scholarship" for foreign students, at any degree level. What UC's own pages actually say (fetched 2026-10-25 for audit row 695 and re-fetched first-hand 2026-10-28): in its prospective-students FAQ, to the question "¿Hay becas para extranjeros en la UC?" the university answers "Si eres estudiante de intercambio, la UC tiene becas de matrícula para Universidades Católicas de América Latina, red CINDA y Universidades Católicas de Chile" - i.e. the only scholarship line it names for foreigners is a tuition scholarship for incoming EXCHANGE students from Latin American Catholic universities, the CINDA network and Chilean Catholic universities (that exchange arrangement was itself retired as record 879 in this same pass). For postgraduates the same FAQ is explicit: "La universidad no entrega ningún tipo de beneficio especial para postgrado" - the university gives no special benefit for postgraduate study, and points to external financing options instead. Its undergraduate funding lines are the academic-excellence prizes and tuition scholarships tied to the Chilean school-leaver admission system (PAES/FUAS machinery), Ministry of Education scholarships and external scholarships - the plausible seed of this row's corruption is the Premio a la Excelencia Académica (Matrícula de Honor), a merit prize for students entering an undergraduate degree through the domestic admission process, not an international award. The stored URL was the domestic admissions portal root (admision.uc.cl, fetched today: PAES-oriented), and an earlier importer incarnation carried an invented USD 8,000 figure (removed 2026-10-26). Realistic routes for a foreigner aiming at UC are external/national instruments - e.g. Chile's ANID national master's/doctoral scholarship competitions (not verified in this pass, so no terms are asserted here; a candidate for a future additions batch under its own name) - not a UC-branded international scholarship. The UC landscape audit is record 695 (retired); for Universidad de Chile see active record 710.$$ , requirements = $$Do not apply on the basis of this record - it is retired and names no real award. UC's own FAQ states that its only scholarship for foreigners is the exchange-student tuition scholarship for the CINDA network and Latin American/Chilean Catholic universities, and that it provides no institutional benefit for postgraduate studies; plan UC study on external funding (such as national ANID competitions, whose current foreigner rules must be read on ANID's official pages) and the international-student admission cases the university publishes.$$ , website_url = $$https://www.uc.cl/informacion-para/futuros-estudiantes/$$, source_url = $$https://www.uc.cl/informacion-para/futuros-estudiantes/$$, application_url = $$https://www.uc.cl/informacion-para/futuros-estudiantes/$$, funding_type = $$RETIRED - invented importer name; no such UC award exists$$, tuition_coverage = $$RETIRED - no coverage of its own; UC's published funding lines are described in the audit row 695.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$Not applicable - retired record.$$ , required_documents = $$[]$$, application_status = $$closed$$, verification_status = $$verified$$, source_reliability = 9, is_active = false, university_id = 89, notes = $$PASS 121 RETIREMENT 2026-10-28 (Chile cluster): invented importer name. First-hand fetch today of the UC prospective-students FAQ (new source 3132) reproduces the finding recorded 2026-10-25 in retired audit row 695: asked '¿Hay becas para extranjeros en la UC?', the university names only the exchange-student tuition scholarship (Latin American Catholic universities / CINDA / Chilean Catholic universities), states it grants no special postgraduate benefit ('La universidad no entrega ningún tipo de beneficio especial para postgrado'), and lists domestic-system funding lines (excellence prizes, tuition scholarships, Mineduc, external) for undergraduates. No 'International Excellence Scholarship' for foreign degree students exists on the fetched pages; stored URL was the domestic admissions portal root (fetched today). Prior history: invented USD 8,000 removed 2026-10-26. us 490 deleted (it contained importer GPA 3.3+/IELTS 6+ claims). Root source 954 retained; (467, 3132) added for audit. Future-additions candidate noted (unverified here): ANID national PG scholarship competitions.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 467 RETURNING id, is_active;

-- 3) Retire 879 (exchange-mobility benefit, out of catalogue scope)
UPDATE scholarships SET title = $$UC Tuition Scholarship for Exchange Students (CINDA & Latin American Catholic Universities) - exchange-mobility benefit, not a degree scholarship (retired)$$, provider = $$Pontificia Universidad Católica de Chile$$, country = $$Chile$$, coverage_type = $$Unspecified$$, amount_usd_value = 0, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL, deadline = $$Retired - this is not a degree scholarship with an application round; it is a tuition benefit that applies inside exchange mobility from partner universities in specific networks (nomination by the home university, per the exchange agreement).$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$none$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Bachelor's"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["RETIRED - only incoming exchange students enrolled at Latin American Catholic universities, CINDA-network or Chilean Catholic universities; not open to direct degree applicants (see description)"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$RETIRED in Pass 121 (2026-10-28): this is a real UC benefit, but it is not a scholarship a degree-seeking applicant can apply for - and it is closed to this catalogue's audience. UC's prospective-students FAQ (fetched first-hand 2026-10-28) answers the question "¿Hay becas para extranjeros en la UC?" with: "Si eres estudiante de intercambio, la UC tiene becas de matrícula para Universidades Católicas de América Latina, red CINDA y Universidades Católicas de Chile" - if you are an EXCHANGE student, UC has tuition scholarships for [students of] Latin American Catholic Universities, the CINDA network and Chilean Catholic Universities, pointing to its incoming-mobility pages (internacionalizacion.uc.cl). In other words, the "scholarship" is the tuition treatment inside exchange agreements: you must already be enrolled at a home university belonging to those regional Catholic/CINDA networks and come to UC for exchange under that university's nomination; there is no open application, no degree at UC, and no route in for a student enrolled in Uzbekistan (no Uzbek institution belongs to those networks). The row's earlier incarnation also carried an invented USD 8,000 figure (removed 2026-10-26), and its stored degree scope ('Bachelor's') and deadline text were placeholders. The same fetched FAQ records that UC gives no special benefit for postgraduate studies and that its undergraduate funding lines belong to the Chilean admission system - see retired audit row 695. Exchange-mobility arrangements are kept out of this degree-scholarship catalogue, so the row is retired rather than repriced.$$ , requirements = $$Do not plan around this record - it is retired. The underlying benefit exists only inside exchange mobility: be enrolled at a Latin American Catholic university, a CINDA-network university or a Chilean Catholic university, and be nominated by that home university for exchange at UC under the agreement. It confers no UC degree and has no open application round.$$ , website_url = $$https://www.uc.cl/informacion-para/futuros-estudiantes/$$, source_url = $$https://www.uc.cl/informacion-para/futuros-estudiantes/$$, application_url = $$https://www.uc.cl/informacion-para/futuros-estudiantes/$$, funding_type = $$RETIRED - exchange-mobility tuition benefit (CINDA / Latin American & Chilean Catholic university networks), not a degree scholarship$$, tuition_coverage = $$RETIRED - exchange tuition treatment under network agreements; no degree-seeker coverage.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$Not applicable - retired record.$$ , required_documents = $$[]$$, application_status = $$closed$$, verification_status = $$verified$$, source_reliability = 9, is_active = false, university_id = 89, notes = $$PASS 121 RETIREMENT 2026-10-28 (Chile cluster): out-of-scope exchange-mobility benefit. First-hand fetch today of the UC prospective-students FAQ (new source 3132): '¿Hay becas para extranjeros en la UC? - Si eres estudiante de intercambio, la UC tiene becas de matrícula para Universidades Católicas de América Latina, red CINDA y Universidades Católicas de Chile.' Requires enrolment at, and nomination by, a home university in those regional networks; no Uzbek institution qualifies, and no degree is conferred. Same finding as retired audit row 695 (2026-10-25); the invented USD 8,000 of an earlier incarnation was removed 2026-10-26. us 460 deleted. (879, 3132) added for audit - record previously had no source link.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 879 RETURNING id, is_active;

